\set ON_ERROR_STOP on
SET ROLE hidden_dissatisfaction_owner;
CREATE TABLE app.parameter_definitions (param_key varchar(40) PRIMARY KEY, unit varchar(10) NOT NULL CHECK(unit IN ('hours','days','orders','times','enum')), min_value integer, max_value integer, allowed_values text[], in_brd boolean NOT NULL, description text NOT NULL);
CREATE TABLE app.parameters (parameter_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, param_key varchar(40) NOT NULL REFERENCES app.parameter_definitions, version integer NOT NULL CHECK(version>0), value text NOT NULL, effective_at timestamptz NOT NULL, actor_id uuid REFERENCES app.users, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(param_key,version));
CREATE TABLE app.audit_events (event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, case_id uuid REFERENCES app.review_cases, order_id varchar(32), actor_id uuid REFERENCES app.users, provenance varchar(20) NOT NULL CHECK(provenance IN ('USER','SYSTEM','QUEUE_SEED')), event_type varchar(20) NOT NULL, old_value text, new_value text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION app.p7_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only',TG_TABLE_NAME; END $$;
CREATE TRIGGER parameters_immutable BEFORE UPDATE OR DELETE ON app.parameters FOR EACH ROW EXECUTE FUNCTION app.p7_append_only();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON app.audit_events FOR EACH ROW EXECUTE FUNCTION app.p7_append_only();
INSERT INTO app.parameter_definitions VALUES
('sla_calendar','enum',NULL,NULL,ARRAY['CALENDAR','BUSINESS_HOURS'],true,'SLA calendar'),('sla_hours_high','hours',1,8760,NULL,true,'High SLA'),('sla_hours_medium','hours',1,8760,NULL,true,'Medium SLA'),('sla_hours_low','hours',1,8760,NULL,true,'Low SLA'),('first_touch_hours','hours',1,8760,NULL,true,'First touch'),('capacity','orders',1,1000,NULL,true,'Capacity'),('capacity_warn','orders',1,1000,NULL,true,'Capacity warning'),('max_contact','times',1,100,NULL,true,'Maximum contacts'),('retry_gap_days','days',0,365,NULL,true,'Retry gap'),('soon_hours','hours',1,8760,NULL,false,'Soon window'),('stale_hours','hours',1,8760,NULL,false,'Stale window'),('aging_days','days',0,3650,NULL,false,'Aging'),('reopen_review_days','days',0,3650,NULL,true,'Reopen review days'),('reopen_review_times','times',0,100,NULL,true,'Reopen review times');
